    /** Случайное название для отрасли (или общее, если отрасль неизвестна). */
    fun random(industryId: String): String {
        val list = byIndustry[industryId] ?: byIndustry.values.first()
        return list[(Math.random() * list.size).toInt().coerceIn(0, list.size - 1)]
    }

    fun all(industryId: String): List<String> = byIndustry[industryId] ?: emptyList()
